"""Lane-b phase-2 reconciliation decisions (post-unblind), one entry per blind id."""

D = {}

UNCH = "cleansingStrength, conditioningLevel, weightPotential and dandruffSupport unchanged from the hash-pinned blind pass (formula-only; claims cannot move them, 3.2)."


def sec_empty(trace, nb="none", conf="high", rat=None, counter=None):
    return {"value": [], "conf": conf, "nb": nb, "trace": trace,
            "rat": rat or "Empty: no distinct secondary positioning with an independent compatible route (Section 8, F2, F3).",
            "counter": counter or "none"}


def usage_regular(trace, losing=None, rat=None):
    return {"value": "regular", "conf": "high", "nb": "none", "code": "none", "ev": [], "losing": losing or [],
            "rat": rat or "Regular: no non-default trigger fires (no U2 frequency wording graded moderate/high, no D1, no dandruff claim plus active, no strong formula).",
            "trace": "Default regular; " + trace, "rules": ["Section 9", "U1", "U2", "U3", "U4", "CL-SRC"]}


def sct_no_position(csa, extra=""):
    return {"value": "not_targeted", "conf": "high", "nb": "none",
            "rat": "Not targeted: no E2 sensitive or dry scalp claim unit graded moderate/high exists (SC1), so the product is not explicitly positioned; " + csa + extra,
            "counter": "none; mildness/protective wording is not targeting (E2a)", "csa": csa,
            "rules": ["Section 10", "SC1", "E2a", "CSA", "MB"], "recon": "claims show no SC1 positioning"}


def sct_no_csa(csa, extra=""):
    return {"value": "not_targeted", "conf": "high", "nb": "none",
            "rat": "Not targeted: whatever the positioning, CSA fails (" + csa + "); without a listed prominent route and without MB a positioned product is not_targeted (Section 10)." + extra,
            "counter": "none", "csa": "none (" + csa + ")",
            "rules": ["Section 10", "CSA", "MB", "SC1", "E3", "E4"], "recon": "formula half already decided it in the blind pass"}


def ordinary_way1(src_high=True, extra=""):
    return {"primary": "ordinary", "secondary": None, "conf": "high" if src_high else "moderate",
            "rat": "S-ORDINARY way 1: no qualifying E2 scalp claim unit after E2a; packet has a manufacturer/pack source -> " + ("high" if src_high else "moderate") + " (13.8)." + extra}


